using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Object=UnityEngine.Object;
public static partial class ScreenshotFollowupRepair {
 public static void FinalizeAndExport(){
  const string prefabPath="Assets/SushiAndFish/CityExpansion/Prefabs/AR_Restaurant.prefab";BackupAsset(prefabPath);var root=PrefabUtility.LoadPrefabContents(prefabPath);try{var back=root.GetComponentsInChildren<MeshRenderer>(true).Single(r=>r.name=="AR_Restaurant_BackWall");var direction=root.transform.forward;var bounds=back.bounds;float limit=float.PositiveInfinity;for(int i=0;i<8;i++){var point=bounds.center+Vector3.Scale(bounds.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1));limit=Mathf.Min(limit,Vector3.Dot(point-root.transform.position,direction));}foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name.StartsWith("AR_Restaurant_KitchenSideWall"))){var f=r.GetComponent<MeshFilter>();var m=Object.Instantiate(f.sharedMesh);var vv=m.vertices;for(int i=0;i<vv.Length;i++){var p=r.transform.TransformPoint(vv[i]);float d=Vector3.Dot(p-root.transform.position,direction);if(d>limit-.002f)p-=direction*(d-limit+.002f);vv[i]=r.transform.InverseTransformPoint(p);}m.vertices=vv;m.RecalculateBounds();f.sharedMesh=SaveMesh(m,"RestaurantPrefabCorner_"+r.name.Replace("-","N").Replace(".","_"));FixCollider(r.transform);}PrefabUtility.SaveAsPrefabAsset(root,prefabPath);}finally{PrefabUtility.UnloadPrefabContents(root);}
  var gs=EditorSceneManager.OpenScene(GS);var ds=EditorSceneManager.OpenScene(DS,OpenSceneMode.Additive);Physics.SyncTransforms();var result=new GeometryStudy{utc=DateTime.UtcNow.ToString("o")};foreach(var t in All(gs).Concat(All(ds)).Where(t=>t.GetComponent<MeshRenderer>()&&t.GetComponent<MeshFilter>())){if(P(t).StartsWith("TownRoadNetwork20261019/ContinuousSurfaces/"))result.roads.Add(Geo(t));if(t.name=="SideWalkTerrainEdge"||P(t).StartsWith("SourceCoastCompletion_20261021/")||P(t)=="RestoredIslandPerimeter_20261021/SM_fence_05")result.coast.Add(Geo(t));}File.WriteAllText(Path.Combine(Reports,"screenshot-final-saved-geometry.json"),JsonUtility.ToJson(result,false));
  var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);var restaurant=All(gs).Single(t=>t.name=="AR_Restaurant");float error=0;foreach(var target in restaurant.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.name.StartsWith("AR_Restaurant_KitchenSideWall"))){var reference=prefab.GetComponentsInChildren<MeshFilter>(true).Single(f=>f.name==target.name);var a=target.sharedMesh.vertices.Select(v=>restaurant.InverseTransformPoint(target.transform.TransformPoint(v))).ToArray();var b=reference.sharedMesh.vertices.Select(v=>prefab.transform.InverseTransformPoint(reference.transform.TransformPoint(v))).ToArray();if(a.Length!=b.Length)throw new Exception("Restaurant corner prefab vertex count mismatch");for(int i=0;i<a.Length;i++)error=Mathf.Max(error,Vector3.Distance(a[i],b[i]));}if(error>.001f)throw new Exception("Restaurant prefab and saved instance differ: "+error);File.WriteAllText(Path.Combine(Reports,"screenshot-restaurant-prefab-readback.json"),"{\"passed\":true,\"maximumLocalVertexError\":"+error.ToString(System.Globalization.CultureInfo.InvariantCulture)+"}");
  PlayerSettings.productName="Deep Blue Sushi";AssetDatabase.SaveAssets();VerifySaved();EditorSceneManager.OpenScene("Assets/Scenes/Main.unity");EditorApplication.Exit(0);
 }
